-- Additional official election records and founding dates for existing party identities.
UPDATE public.political_organizations AS party
SET name = CASE WHEN party.name = party.short_name THEN evidence.name ELSE party.name END,
    profile_evidence = party.profile_evidence || evidence.facts,
    updated_at = now()
FROM (VALUES
  ('ORG-PARTY-JKPC', 'Jammu & Kashmir People Conference', '[{"kind":"electionProfile","election":"assembly","year":2024,"state":"JK","category":"registered","eciName":"Jammu & Kashmir People Conference","eciCode":"JPC","seatsWon":1,"sourceUrl":"https://www.eci.gov.in/eci-backend/public/all_files/AE-2024-statistical-report-JK/3-List-Of-Political-Parties-Participated.pdf","resultsSourceUrl":"https://www.eci.gov.in/eci-backend/public/all_files/AE-2024-statistical-report-JK/2-List-of-Successful-Candidates.pdf","symbol":"Apple"}]'::jsonb),
  ('ORG-PARTY-RD', 'Raijor Dal', '[{"kind":"electionProfile","election":"assembly","year":2026,"state":"AS","category":"registered","eciName":"Raijor Dal","eciCode":"RJRD","seatsWon":2,"sourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Assam_2026_2026/3-List_Of_Political_Parties_Participated_1778163955.pdf","resultsSourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Assam_2026_2026/2-List_of_Successful_Candidates_1778163955.pdf","symbol":"Gas cylinder"}]'::jsonb),
  ('ORG-PARTY-KC', 'Kerala Congress', '[{"kind":"electionProfile","election":"assembly","year":2026,"state":"KL","category":"state","eciName":"Kerala Congress","eciCode":"KEC","seatsWon":7,"sourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Kerala_2026_2026/3-List_Of_Political_Parties_Participated_1778164525.pdf","resultsSourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Kerala_2026_2026/2-List_of_Successful_Candidates_1778164525.pdf","symbol":"Auto- rickshaw"}]'::jsonb),
  ('ORG-PARTY-KCB', 'Kerala Congress (B)', '[{"kind":"electionProfile","election":"assembly","year":2026,"state":"KL","category":"registered","eciName":"Kerala Congress (b)","eciCode":"KEC(B)","seatsWon":0,"sourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Kerala_2026_2026/3-List_Of_Political_Parties_Participated_1778164525.pdf","resultsSourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Kerala_2026_2026/2-List_of_Successful_Candidates_1778164525.pdf"}]'::jsonb),
  ('ORG-PARTY-KCJ', 'Kerala Congress (Jacob)', '[{"kind":"electionProfile","election":"assembly","year":2026,"state":"KL","category":"registered","eciName":"Kerala Congress (jacob)","eciCode":"KEC(J)","seatsWon":1,"sourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Kerala_2026_2026/3-List_Of_Political_Parties_Participated_1778164525.pdf","resultsSourceUrl":"https://www.eci.gov.in/eci-backend/public//all_files/election_report/General_Election_to_the_Legislative_Assembly_of_Kerala_2026_2026/2-List_of_Successful_Candidates_1778164525.pdf","symbol":"Coconut farm"}]'::jsonb),
  ('ORG-PARTY-GFP', 'Goa Forward Party', '[{"kind":"assemblyElection","year":2022,"state":"GA","sourceUrl":"https://www.dpse.goa.gov.in/SHB2022-23.pdf"}]'::jsonb),
  ('ORG-PARTY-MGP', 'Maharashtrawadi Gomantak', '[{"kind":"assemblyElection","year":2022,"state":"GA","sourceUrl":"https://www.dpse.goa.gov.in/SHB2022-23.pdf"}]'::jsonb),
  ('ORG-PARTY-HSPDP', 'Hill State People''s Democratic Party', '[{"kind":"assemblyElection","year":2023,"state":"ML","sourceUrl":"https://ceomeghalaya.nic.in/electionconducted/mla2023/ac-result-report.pdf"}]'::jsonb),
  ('ORG-PARTY-PDF', 'People''s Democratic Front', '[{"kind":"assemblyElection","year":2023,"state":"ML","sourceUrl":"https://ceomeghalaya.nic.in/electionconducted/mla2023/ac-result-report.pdf"}]'::jsonb),
  ('ORG-PARTY-TMP', 'Tipra Motha Party', '[{"kind":"assemblyElection","year":2023,"state":"TR","sourceUrl":"https://ceochhattisgarh.nic.in/assets/pdf%20files/RecognitionDecrecognitionPoliticalPartypdf_compressed.pdf"}]'::jsonb),
  ('ORG-PARTY-SKP', 'Sarvodaya Karnataka Paksha', '[{"kind":"assemblyElection","year":2023,"state":"KA","sourceUrl":"https://kla.kar.nic.in/assembly/election/electoral_june2023_14062023.pdf"}]'::jsonb),
  ('ORG-PARTY-KPA', 'Kuki People''s Alliance', '[{"kind":"assemblyElection","year":2022,"state":"MN","sourceUrl":"https://ceomanipur.nic.in/Documents/gazette/GE2022/Elected%20Members.pdf"},{"kind":"registered","year":2021,"sourceUrl":"https://ceomanipur.nic.in/Documents/RTI/Section%204%281%29%28b%29%28xvii%29.pdf"}]'::jsonb),
  ('ORG-PARTY-AAP', 'Aam Aadmi Party', '[{"kind":"founded","year":2012,"sourceUrl":"https://archive.aamaadmiparty.org/about/our-history/"}]'::jsonb),
  ('ORG-PARTY-AITC', 'All India Trinamool Congress', '[{"kind":"founded","year":1998,"sourceUrl":"https://aitcofficial.org/the-party/","founder":"Mamata Banerjee"}]'::jsonb),
  ('ORG-PARTY-CPIM', 'Communist Party of India (Marxist)', '[{"kind":"founded","year":1964,"sourceUrl":"https://cpim.org/page-about-us/"}]'::jsonb),
  ('ORG-PARTY-AIADMK', 'All India Anna Dravida Munnetra Kazhagam', '[{"kind":"founded","year":1972,"sourceUrl":"https://aiadmk.com/admk-history/","founder":"M. G. Ramachandran"}]'::jsonb),
  ('ORG-PARTY-DMK', 'Dravida Munnetra Kazhagam', '[{"kind":"founded","year":1949,"sourceUrl":"https://www.dmk.in/DMK_Manifesto_English_2026.pdf","founder":"C. N. Annadurai"}]'::jsonb),
  ('ORG-PARTY-SP', 'Samajwadi Party', '[{"kind":"founded","year":1992,"sourceUrl":"https://samajwadiparty.in/about-the-party","founder":"Mulayam Singh Yadav"}]'::jsonb)
) AS evidence(id, name, facts)
WHERE party.id = evidence.id
  AND party.org_type = 'political_party'
  AND party.provenance_id IS NOT NULL
  AND NOT party.profile_evidence @> evidence.facts;
